SELECT 
  ROUND(
    CAST(SUM(CASE WHEN customer_state = 'SP' THEN 1 ELSE 0 END) AS REAL) / COUNT(*),
    2
  ) AS sp_customer_ratio
FROM (SELECT DISTINCT customer_unique_id, customer_state FROM customers) LIMIT 1000;

SELECT ROUND(AVG(cat_count), 2) AS avg_products_per_category
FROM (
  SELECT product_category_name, COUNT(DISTINCT product_id) AS cat_count
  FROM products
  GROUP BY product_category_name
) LIMIT 1000;
